import re,glob,collections
def strip(t):
    out=[]
    for line in t.split('\n'):
        i=0;res=''
        while i<len(line):
            c=line[i]
            if c=='\\' and i+1<len(line):
                res+=line[i:i+2]; i+=2; continue
            if c=='%': break
            res+=c; i+=1
        out.append(res)
    return '\n'.join(out)
cnt=collections.Counter()
for fn in sorted(glob.glob('*.tex')):
    t=strip(open(fn).read())
    for m in re.finditer(r'\\begin\{([a-zA-Z*]+)\}',t): cnt[m.group(1)]+=1
for k,v in cnt.most_common(): print(v,k)
PY
